import {readFileSync} from 'node:fs';
import {dirname,join} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
// Installed runtime.json is generated by the local installer from its actual source root.
const root=JSON.parse(readFileSync(join(dirname(fileURLToPath(import.meta.url)),'runtime.json'),'utf8')).source_root;
const {runHook}=await import(pathToFileURL(join(root,'apps/local-module-review/hook.ts')).href);
await runHook();
